<div class="tot"><div><span>Subtotal</span><span>${RWF(sub)}</span></div><div><span>Discount <select id="ds" style="padding:2px 6px">${[0,5,10,15].map(x=>`<option value="${x}" ${x==S.disc?'selected':''}>${x}%</option>`).join('')}</select></span><span>−${RWF(d)}</span></div><div><span>VAT 18% (included)</span><span>${RWF((sub-d)*.18/1.18)}</span></div><div class="t"><span>Total</span><span>${RWF(sub-d)}</span></div></div>
