const o=modal(`<h3 style="font-size:18px">${p.id?'Edit':'Add'} product</h3><div class="fm"><label class="w">Name<input id="f1" value="${p.name}"></label><label>Category<select id="f2">${Object.keys(C).map(c=>`<option ${c==p.cat?'selected':''}>${c}</option>`).join('')}</select></label><label>SKU<input id="f3" value="${p.sku}"></label><label>Buying price<input id="f4" type="number" value="${p.cost}"></label><label>Selling price<input id="f5" type="number" value="${p.price}"></label><label>Stock<input id="f6" type="number" value="${p.qty}"></label><label>Minimum level<input id="f7" type="number" value="${p.min}"></label></div><div class="row" style="margin-top:18px;justify-content:flex-end"><button class="btn" onclick="this.closest('.ov').remove()">Cancel</button><button class="btn p" id="sv">Save product</button></div>`);
