document.querySelectorAll('aside a').forEach(a=>a.classList.toggle('on',a.dataset.r==r));$('#pt').textContent=r=='Dashboard'?'Good morning, Admin':r;$('#ps').textContent=r=='Dashboard'?new Date().toDateString():'';
if(r=='Point of Sale'){const q=$('#pq');q.oninput=()=>{S.q=q.value;const s=q.selectionStart;render();$('#pq').focus();$('#pq').setSelectionRange(s,s)};q.onkeydown=e=>{if(e.key=='Enter'&&P.find(p=>p.sku==q.value)){add(P.find(p=>p.sku==q.value).id);S.q='';render()}};$('#co').onclick=checkout;$('#cu').onchange=e=>S.cust=e.target.value;$('#ds').onchange=e=>{S.disc=+e.target.value;render()};$('#clr').onclick=()=>{S.cart=[];render()};$('#hold').onclick=()=>{if(S.cart.length){S.held.push(S.cart);S.cart=[];toast('Sale held');render()}};$('#resume').onclick=()=>{if(S.held.length){S.cart=S.held.pop();render()}else toast('No held sales')}}
