function repo(){const D=data(),B=D.B,tabs=[['ov','General overview'],['dy','Daily report'],['wk','Weekly report'],['mo','Monthly income'],['un','Unpaid invoices']];let body;
if(S.rt=='ov'){const mx=(D.top[0]||{r:1}).r;
body=`<div class="g k4">${[['Total revenue',RWF(D.rev),'trend','#dcfce7'],['Total sales',D.ord,'receipt','#ede9fe'],['Average order',RWF(D.avg),'wallet','#dbeafe'],['Gross profit',RWF(D.gp),'chart','#ffedd5']].map(x=>`<div class="cd kp"><div class="ic" style="background:${x[3]}">${IC[x[2]]}</div><div><div class="sub">${x[0]}</div><div class="kv">${x[1]}</div></div></div>`).join('')}</div>
<h3 style="margin:24px 0 12px">Payment breakdown</h3><div class="g g3"><div class="cd" style="border-left:4px solid #f97316"><div class="sub">Total cash</div><div class="kv" style="font-size:28px;margin:4px 0">${RWF(B.Cash)}</div><b style="color:#c2410c;font-size:12px">Physical currency</b></div>
<div class="cd" style="border-left:4px solid #3b82f6"><div class="sub">Mobile money and digital</div><div class="kv" style="font-size:28px;margin:4px 0">${RWF(D.dg)}</div><b style="color:#1d4ed8;font-size:12px">MoMo, card and transfer</b></div>
<div class="cd" style="background:#0f8a7a;border:0;color:#fff"><div style="opacity:.8">Total combined</div><div class="kv" style="font-size:28px;margin:4px 0">${RWF(D.rev)}</div><b style="font-size:12px">Grand total collected</b></div></div>
<div class="g" style="margin-top:18px;grid-template-columns:repeat(auto-fit,minmax(320px,1fr))"><div class="cd"><h3>Customer statistics</h3><div class="kp" style="margin-bottom:6px"><div class="ic" style="background:#dbeafe">${IC.users}</div><div><div class="sub">Registered customers</div><div class="kv">837</div></div></div>${[['Walk-in sales',D.wi],['Registered customer sales',D.ord-D.wi],['Total sales',D.ord],['Average order value',RWF(D.avg)]].map(x=>`<div class="li"><div class="sub">${x[0]}</div><b>${x[1]}</b></div>`).join('')}</div>
<div class="cd"><h3>Most sold products</h3>${D.top.map(t=>`<div style="margin-bottom:14px"><div class="row sub"><span><b style="color:var(--tx)">${t.n}</b></span><span>${t.u} units · ${RWF(t.r)}</span></div><div class="bar" style="margin-top:6px"><i style="width:${t.r/mx*100}%"></i></div></div>`).join('')||'<div class="sub">No sales in this period yet</div>'}</div></div>`;
}else if(S.rt=='dy'){body=`<div class="cd"><h3>Transaction history (${D.ord} sales)</h3>${D.ord?txT(D):'<div class="sub">No sales in this period yet</div>'}</div>`}
else if(S.rt=='wk')body=wkBody();else if(S.rt=='mo')body=moBody();else body=`<div class="cd">${tbl(repData(),S.rt=='un')}</div>`;
return `<div class="row" style="flex-wrap:wrap;margin-bottom:14px"><div class="chips" style="margin:0">${tabs.map(t=>`<span class="chip ${t[0]==S.rt?'on':''}" data-rtab="${t[0]}">${t[1]}</span>`).join('')}</div><div class="row"><button class="btn" data-prev="1">Preview report</button><button class="btn" data-pdf="1">Download PDF</button><button class="btn" data-csv="1">Export CSV</button></div></div>
<div class="cd" style="margin-bottom:18px;padding:14px 18px"><div class="row" style="flex-wrap:wrap"><div class="row" style="flex-wrap:wrap"><b>Filter period</b><select id="rps">${[['1','Today'],['7','Last 7 days'],['30','Last 30 days'],['c','Custom']].map(o=>`<option value="${o[0]}" ${o[0]==S.rp?'selected':''}>${o[1]}</option>`).join('')}</select><input type="date" id="rf" value="${S.rf}"><span class="sub">to</span><input type="date" id="rt2" value="${S.rto}"></div><button class="btn p" data-apply="1">Apply filters</button></div><div class="sub" style="margin-top:8px">Showing data from ${S.rf} to ${S.rto}</div></div>${body}`}
const csvOf=()=>{const d=repData();return[d.head,...d.rows].map(r=>r.map(c=>'"'+String(c).replace(/<[^>]*>/g,'').replace(/"/g,'""')+'"').join(',')).join('\n')};
const dt=(h,rows,c)=>`<table class="dt" style="--h:${c}"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`,sc=t=>`<div style="margin:26px 0 10px;font-size:12px;font-weight:700;letter-spacing:.08em;color:#8a94a6">${t}</div>`;
function docHTML(){const D=data(),k=S.rt,d=repData();let h=`<div style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap"><div><img src="${LD}" alt="MarketFlow" style="height:40px;display:block"><div style="color:#0f8a7a;font-weight:700;letter-spacing:.08em;font-size:11px;margin-top:8px">SUPERMARKET MANAGEMENT SYSTEM</div><div style="font-size:11px;color:#555">TEL: +250 788 000 000 / +250 722 000 000 · Kigali, Rwanda</div></div><div style="text-align:right;font-size:11px;color:#777;line-height:1.7"><div>Generated: ${new Date().toLocaleString()}</div><div>Period: ${S.rf} – ${S.rto}</div></div></div><h2 style="font-size:22px;margin:24px 0 2px;letter-spacing:-.01em;color:#111">${titles[k].toUpperCase()}</h2><div style="color:#666;font-size:13px;padding-bottom:14px;border-bottom:2px solid #ddd">Business performance overview</div>`;
if(k=='ov'||k=='dy'||k=='wk'){h+=sc('SUMMARY METRICS')+`<div style="display:grid;grid-template-columns:1fr 1fr;gap:0 28px">${sumRows(D).map(r=>`<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div>`}
if(k=='ov'||k=='dy')h+=sc('TOP PRODUCTS')+dt(['Product','Units sold','Revenue'],D.top.map(t=>[t.n,t.u,RWF(t.r)]),'#0f8a7a');
if(k=='dy')h+=sc('TRANSACTION HISTORY ('+D.ord+' SALES)')+dt([...(multi()?['Date']:[]),'Time','Customer','Items bought','Payment','Total'],D.tx.map(x=>[...(multi()?[x.d]:[]),x.tm,x.c,its(x),x.pay,RWF(x.total)]).concat([[...(multi()?['']:[]),'','<b>TOTAL</b>','','',`<b>${RWF(D.rev)}</b>`]]),'#1f2937');
if(k=='wk')h+=wkDoc(D);else if(k=='mo')h+=moDoc();else if(k=='un')h+=sc('UNPAID INVOICES')+dt(d.head,d.rows,'#0f8a7a');
return `<div class="doc" style="background:#fff;color:#111;padding:38px;border-radius:14px">${h}<div style="margin-top:30px;padding-top:12px;border-top:1px solid #e5e7eb;font-size:11px;color:#888;text-align:center">Generated by MarketFlow · Demo data</div></div>`}
function monthly(){const n=new Date(),o=[];for(let k=5;k>=0;k--){const a=new Date(Date.UTC(n.getUTCFullYear(),n.getUTCMonth()-k,1)),e=new Date(Date.UTC(a.getUTCFullYear(),a.getUTCMonth()+1,0));let c=0,r=0,g=0;for(let t=a.getTime();t<=Math.min(e.getTime(),T0());t+=864e5)txAll(t).forEach(x=>{c++;r+=x.total;g+=cg(x)});o.push([a.toLocaleString('en',{month:'long',year:'numeric',timeZone:'UTC'}),c,RWF(r),RWF(g),RWF(r-g),RWF(r-g-r*.1)])}return o.reverse()}
function mt(){const n=new Date();let c=0,r=0,g=0;for(let t=Date.UTC(n.getUTCFullYear(),n.getUTCMonth(),1);t<=T0();t+=864e5)txAll(t).forEach(x=>{c++;r+=x.total;g+=x.total-cg(x)});return{c,r,g}}
const recent=()=>txAll(T0()).slice().reverse().slice(0,5).map(x=>({c:x.c,id:x.id,t:x.tm,pay:x.pay,total:x.total}));
function topW(){const m={};for(let k=0;k<7;k++)txAll(T0()-k*864e5).forEach(x=>x.items.forEach(i=>m[i[0]]=(m[i[0]]||0)+i[1]*i[2]));return Object.entries(m).sort((a,b)=>b[1]-a[1]).map(e=>P.find(p=>p.name==e[0])).filter(Boolean).slice(0,4)}
function vy(){const nw=new Date().toTimeString().slice(0,5),a=txAll(T0()).reduce((s,x)=>s+x.total,0),b=txAll(T0()-864e5).filter(x=>x.tm<=nw).reduce((s,x)=>s+x.total,0);if(!b)return '';const p=(a-b)/b*100;return `<span class="pill ${p>=0?'up':'rd'}">${p>=0?'▲':'▼'} ${Math.abs(p).toFixed(1)}% vs yesterday so far</span>`}
const md=t=>new Date(t).toLocaleDateString('en',{day:'numeric',month:'short',timeZone:'UTC'}),agg=(a,b)=>{let c=0,r=0,g=0;const days=[];for(let t=a;t<=Math.min(b,T0());t+=864e5){const x=txAll(t);x.forEach(y=>{c++;r+=y.total;g+=cg(y)});days.push({t,x})}return{c,r,g,days}};
const dayTbl=days=>`<div class="tw"><table class="in"><thead><tr><th>Time</th><th>Customer</th><th>Items bought</th><th>Payment</th><th>Total</th></tr></thead><tbody>${days.slice().reverse().map(d=>`<tr class="dh"><td colspan="5">${new Date(d.t).toLocaleDateString('en',{weekday:'long',day:'numeric',month:'short',timeZone:'UTC'})} · ${d.x.length} sales · ${RWF(d.x.reduce((s,y)=>s+y.total,0))}</td></tr>`+d.x.slice().reverse().map(y=>`<tr><td>${y.tm}</td><td><b>${y.c}</b></td><td>${its(y)}</td><td>${y.pay}</td><td><b>${RWF(y.total)}</b></td></tr>`).join('')).join('')}</tbody></table></div>`;
function xrow(k,cells,inner,cols){const o=S.op[k];return `<tr class="xr ${o?'o':''}" data-tg="${k}"><td><i class="cv"></i>${cells[0]}</td>${cells.slice(1).map(c=>`<td>${c}</td>`).join('')}</tr>`+(o?`<tr class="xb"><td colspan="${cols}">${inner()}</td></tr>`:'')}
const xt=(head,rows,hint)=>`<div class="cd"><div class="sub" style="margin-bottom:10px">${hint}</div><div class="tw"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div></div>`;
function wkBody(){const D=data(),o=[];for(let i=0;i<D.L.length;i+=7){const L=D.L.slice(i,i+7),A=agg(L[0],L[L.length-1]);o.unshift(xrow('w:'+ds(L[0]),['Week of '+md(L[0])+' – '+md(L[L.length-1]),A.c,RWF(A.r),RWF(A.r-A.g)],()=>dayTbl(A.days),4))}return xt(['Week','Sales','Revenue','Gross profit'],o.join(''),'Select a week to see its sales, grouped by day')}
function moBody(){const n=new Date(),o=[];for(let k=0;k<6;k++){const a=Date.UTC(n.getUTCFullYear(),n.getUTCMonth()-k,1),e=Date.UTC(n.getUTCFullYear(),n.getUTCMonth()-k+1,0),ym=ds(a).slice(0,7),M=agg(a,e);
o.push(xrow('m:'+ym,[new Date(a).toLocaleString('en',{month:'long',year:'numeric',timeZone:'UTC'}),M.c,RWF(M.r),RWF(M.g),RWF(M.r-M.g),RWF(M.r-M.g-M.r*.1)],()=>{const w=[];for(let s=a,j=1;s<=Math.min(e,T0());s+=7*864e5,j++){const en=Math.min(s+6*864e5,e),W=agg(s,en);w.push(xrow('mw:'+ym+':'+j,['Week '+j+' · '+md(s)+' – '+md(en),W.c,RWF(W.r),RWF(W.g),RWF(W.r-W.g),RWF(W.r-W.g-W.r*.1)],()=>dayTbl(W.days),6))}return `<table class="in"><thead><tr><th>Week</th><th>Sales</th><th>Revenue</th><th>Cost of goods</th><th>Gross profit</th><th>Net profit</th></tr></thead><tbody>${w.join('')}</tbody></table>`},6))}
return xt(['Month','Sales','Revenue','Cost of goods','Gross profit','Net profit'],o.join(''),'Select a month to see its weeks, then a week to see its days and sales')}
const dayDoc=days=>`<table class="dt" style="--h:#1f2937"><thead><tr><th>Time</th><th>Customer</th><th>Items bought</th><th>Payment</th><th>Total</th></tr></thead><tbody>${days.slice().reverse().map(d=>`<tr><td colspan="5" style="background:#e3f4ef!important;color:#0f766e;font-weight:700">${new Date(d.t).toLocaleDateString('en',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})} · ${d.x.length} sales · ${RWF(d.x.reduce((s,y)=>s+y.total,0))}</td></tr>`+d.x.slice().reverse().map(y=>`<tr><td>${y.tm}</td><td>${y.c}</td><td>${its(y)}</td><td>${y.pay}</td><td><b>${RWF(y.total)}</b></td></tr>`).join('')).join('')}</tbody></table>`;
const kv=r=>`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin:8px 0 12px">${r.map(x=>`<div style="background:#f3f4f6;border-radius:10px;padding:8px 12px"><div style="font-size:11px;color:#666">${x[0]}</div><b style="font-size:13px">${x[1]}</b></div>`).join('')}</div>`;
function wkDoc(D){const W=[];for(let i=0;i<D.L.length;i+=7){const L=D.L.slice(i,i+7);W.unshift({A:agg(L[0],L[L.length-1]),lb:md(L[0])+' – '+md(L[L.length-1])})}
return sc('WEEKLY SUMMARY')+dt(['Week','Sales','Revenue','Gross profit'],W.map(w=>[w.lb,w.A.c,RWF(w.A.r),RWF(w.A.r-w.A.g)]),'#0f8a7a')+W.map(w=>sc('WEEK OF '+w.lb.toUpperCase()+' · ALL SALES')+kv([['Sales',w.A.c],['Revenue',RWF(w.A.r)],['Gross profit',RWF(w.A.r-w.A.g)]])+dayDoc(w.A.days)).join('')}
function moDoc(){const n=new Date(),M=[];for(let k=0;k<6;k++){const a=Date.UTC(n.getUTCFullYear(),n.getUTCMonth()-k,1),e=Date.UTC(n.getUTCFullYear(),n.getUTCMonth()-k+1,0);M.push({a,e,A:agg(a,e),lb:new Date(a).toLocaleString('en',{month:'long',year:'numeric',timeZone:'UTC'})})}
const net=A=>A.r-A.g-A.r*.1;
return sc('MONTHLY SUMMARY')+dt(['Month','Sales','Revenue','Cost of goods','Gross profit','Net profit'],M.map(m=>[m.lb,m.A.c,RWF(m.A.r),RWF(m.A.g),RWF(m.A.r-m.A.g),RWF(net(m.A))]),'#0f8a7a')+M.map(m=>{let s='';for(let t=m.a,j=1;t<=Math.min(m.e,T0());t+=7*864e5,j++){const en=Math.min(t+6*864e5,m.e),W=agg(t,en);s+=`<div style="margin:16px 0 4px;font-weight:700;font-size:13px">Week ${j} · ${md(t)} – ${md(en)}</div>`+kv([['Sales',W.c],['Revenue',RWF(W.r)],['Gross profit',RWF(W.r-W.g)],['Net profit',RWF(net(W))]])+dayDoc(W.days)}return sc(m.lb.toUpperCase()+' · WEEKS, DAYS AND SALES')+kv([['Sales',m.A.c],['Revenue',RWF(m.A.r)],['Cost of goods',RWF(m.A.g)],['Gross profit',RWF(m.A.r-m.A.g)],['Net profit',RWF(net(m.A))]])+s}).join('')}
const doPrint=()=>{try{window.print()}catch(x){toast('Open the app in its own tab to print or save as PDF')}};
function prevM(){const o=modal(`<div class="np row" style="margin-bottom:12px"><b style="color:#fff">Report preview</b><div class="row"><button class="btn" onclick="this.closest('.ov').remove()">Close</button><button class="btn p" id="pp">Print / Save as PDF</button></div></div>${docHTML()}`);o.firstChild.style.cssText='width:min(860px,100%);background:transparent;box-shadow:none;padding:0;max-height:94vh;overflow:auto';$('#pp').onclick=doPrint}
document.addEventListener('change',e=>{if(e.target.id=='rps'){const v=e.target.value;S.rp=v;if(v!='c'){S.rto=ds(T0());S.rf=ds(T0()-(v-1)*864e5)}render()}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-np],[data-rtab],[data-apply],[data-paid],[data-prev],[data-csv],[data-pdf],[data-tg]');if(!t)return;const d=t.dataset;
if(d.tg){const y=$('#v').scrollTop;S.op[d.tg]=!S.op[d.tg];render();$('#v').scrollTop=y}else if(d.np)form();else if(d.rtab){S.rt=d.rtab;if(d.rtab=='dy'){S.rp='1';S.rf=S.rto=ds(T0())}else if(d.rtab=='wk'){S.rp='c';S.rf=ds(T0()-27*864e5);S.rto=ds(T0())}render()}else if(d.apply){const f=$('#rf').value,u=$('#rt2').value;if(!f||!u||f>u)return toast('Choose a valid date range');S.rf=f;S.rto=u;S.rp='c';render();toast('Filters applied')}
else if(d.paid){const u=UN.find(x=>x[0]==d.paid);S.paid[d.paid]=1;S.sales.unshift({id:d.paid,t:new Date().toTimeString().slice(0,8),c:u[1],total:u[2],pay:'Bank Transfer',items:[['Invoice '+d.paid+' payment',1,u[2]]]});toast(d.paid+' marked as paid and added to today’s sales');render()}else if(d.prev)prevM();
else if(d.csv){const o=modal(`<h3>Export CSV</h3><p class="sub">Copy this data into Excel or Google Sheets. Direct file downloads need the real backend.</p><textarea id="cv" readonly style="width:100%;height:200px;font:12px ui-monospace,monospace;border:1px solid var(--bd);border-radius:11px;padding:10px;background:var(--bg);color:var(--tx)"></textarea><div class="row" style="margin-top:14px;justify-content:flex-end"><button class="btn" onclick="this.closest('.ov').remove()">Close</button><button class="btn p" id="cp">Copy CSV</button></div>`);$('#cv').value=csvOf();$('#cp').onclick=()=>{$('#cv').select();try{navigator.clipboard.writeText($('#cv').value).then(()=>toast('CSV copied'),()=>{document.execCommand('copy');toast('CSV copied')})}catch(x){try{document.execCommand('copy')}catch(y){}toast('CSV selected. Press Ctrl+C to copy')}}}
else if(d.pdf){prevM();setTimeout(doPrint,500)}});

let tl;const TS='.tilt,.pc,.hero,.k4>.cd,.g3>.cd';
document.addEventListener('mousemove',e=>{const t=e.target.closest&&e.target.closest(TS);if(tl&&tl!==t)tl.style.transform='';tl=t;if(!t)return;const r=t.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5,m=t.classList.contains('lc')?8:t.classList.contains('hero')?4:10;t.style.transform=`perspective(900px) rotateX(${-y*m}deg) rotateY(${x*m}deg) scale(1.02)`});
document.addEventListener('mouseout',e=>{if(!e.relatedTarget&&tl){tl.style.transform='';tl=null}});
fetch('/api/auth/me',{credentials:'same-origin'}).then(r=>r.ok?r.json():null).then(d=>{if(d&&d.user){window.MF_USER=d.user;start()}else loginView()}).catch(loginView);
